124	        @Override
125	        public boolean canTransitionTo(ShipmentStatus nextStatus) {
126	            return nextStatus == OUT_FOR_DELIVERY || nextStatus == DELAYED || nextStatus == CANCELED
127	                    || nextStatus == DELIVERED;
128	        }
129	    },
130	    OUT_FOR_DELIVERY {
131	        @Override
132	        public boolean canTransitionTo(ShipmentStatus nextStatus) {
133	            return nextStatus == DELIVERED || nextStatus == FAILED_DELIVERY || nextStatus == CANCELED;
134	        }
135	    },
136	    DELIVERED {
137	        @Override
138	        public boolean canTransitionTo(ShipmentStatus nextStatus) {
139	            return false; // 배송 완료 이후로는 상태 전환 없음
140	        }
141	    },
142	    RETURNED {
143	        @Override
144	        public boolean canTransitionTo(ShipmentStatus nextStatus) {
145	            return nextStatus == CANCELED;
146	        }
147	    },
148	    CANCELED {
149	        @Override
150	        public boolean canTransitionTo(ShipmentStatus nextStatus) {
151	            return false; // 취소 이후 상태 전환 없음
152	        }
153	    },
154	    DELAYED {
155	        @Override
156	        public boolean canTransitionTo(ShipmentStatus nextStatus) {
157	            return nextStatus == IN_TRANSIT || nextStatus == CANCELED;
158	        }
159	    },
160	    FAILED_DELIVERY {
161	        @Override
162	        public boolean canTransitionTo(ShipmentStatus nextStatus) {
163	            return nextStatus == RETURNED || nextStatus == OUT_FOR_DELIVERY || nextStatus == CANCELED;
164	        }
165	    };
166	
167	    public abstract boolean canTransitionTo(ShipmentStatus nextStatus);
168	}

