 10	import lombok.extern.slf4j.Slf4j;
 11	import org.springframework.http.ResponseEntity;
 12	import org.springframework.validation.annotation.Validated;
 13	import org.springframework.web.bind.annotation.*;
 14	
 15	/**
 16	 * 주문 배송 정보 명령 컨트롤러
 17	 */
 18	@Slf4j
 19	@RestController
 20	@RequestMapping("/shipments/order")
 21	@RequiredArgsConstructor
 22	public class OrderShipmentCommandController {
 23	
 24	    private final OrderShipmentCommandService orderShipmentCommandService;
 25	
 26	    /**
 27	     * 배송 운송장 정보를 업데이트합니다.
 28	     *
 29	     * @param shipmentId 배송 ID
 30	     * @param requestDto 운송장 정보 DTO
 31	     * @return 성공 응답
 32	     */
 33	    @PatchMapping("/{shipmentId}/status")
 34	    public ResponseEntity<Void> updateTrackingInfo(
 35	            @PathVariable Long shipmentId,
 36	            @Validated @RequestBody OrderShipmentRequestDto requestDto
 37	    ) {
 38	        log.info("배송 운송장 정보 업데이트 요청: shipmentId={}, courier={}, trackingNumber={}",
 39	                shipmentId, requestDto.getCourier(), requestDto.getTrackingNumber());
 40	
 41	        orderShipmentCommandService.updateTrackingInfo(
 42	                shipmentId,
 43	                requestDto.getCourier(),
 44	                requestDto.getTrackingNumber()
 45	        );
 46	
 47	        log.info("배송 운송장 정보 업데이트 완료: shipmentId={}", shipmentId);
 48	        return ResponseEntity.ok().build();
 49	    }
 50	
 51	    /**
 52	     * 단일 배송 건에 대해 상태를 즉시 조회하고 업데이트합니다.
 53	     *
 54	     * @param shipmentId 배송 ID
 55	     * @param requestDto 운송장 정보 DTO
 56	     * @return 배송 상태 응답
 57	     */
 58	    @PostMapping("/{shipmentId}/check-status")
 59	    public ResponseEntity<ShipmentStatusResponse> updateAndCheckStatus(
 60	            @PathVariable("shipmentId") Long shipmentId,
 61	            @Validated @RequestBody OrderShipmentRequestDto requestDto
 62	    ) {
 63	        log.info("배송 상태 즉시 조회 요청: shipmentId={}, courier={}, trackingNumber={}",
 64	                shipmentId, requestDto.getCourier(), requestDto.getTrackingNumber());
 65	
 66	        try {
 67	            // 서비스에서 상태 업데이트 & 조회
 68	            ShipmentStatus updatedStatus = orderShipmentCommandService.updateAndCheckShipmentStatus(
 69	                    shipmentId,
 70	                    requestDto.getCourier(),
 71	                    requestDto.getTrackingNumber()
 72	            );
 73	
 74	            // 응답 DTO로 감싸서 반환
 75	            ShipmentStatusResponse response = new ShipmentStatusResponse(updatedStatus);
 76	            log.info("배송 상태 조회 완료: shipmentId={}, status={}", shipmentId, updatedStatus);
 77	
 78	            return ResponseEntity.ok(response);
 79	
 80	        } catch (ShipmentException e) {
 81	            log.error("배송 상태 조회 실패 (ShipmentException): shipmentId={}, code={}, message={}",
 82	                    shipmentId, e.getErrorCode().getCode(), e.getMessage());
 83	
 84	            return ResponseEntity
 85	                    .status(e.getErrorCode().getStatus())
 86	                    .build();
 87	
 88	        } catch (Exception e) {
 89	            log.error("배송 상태 조회 실패 (일반 예외): shipmentId={}, error={}",
 90	                    shipmentId, e.getMessage(), e);
 91	
 92	            return ResponseEntity.badRequest().build();
 93	        }
 94	    }
 95	
 96	    /**
 97	     * 단일 배송 건에 대해 상태를 즉시 조회하고 문자열로 반환합니다.
 98	     *
 99	     * @param shipmentId 배송 ID
100	     * @param requestDto 운송장 정보 DTO
101	     * @return 배송 상태 문자열
102	     */
103	    @PostMapping("/{shipmentId}/check-status-string")
104	    public ResponseEntity<String> updateAndCheckStatusAsString(
105	            @PathVariable("shipmentId") Long shipmentId,
106	            @Validated @RequestBody OrderShipmentRequestDto requestDto
107	    ) {
108	        log.info("배송 상태 즉시 조회 요청 (문자열 응답): shipmentId={}, courier={}, trackingNumber={}",
109	                shipmentId, requestDto.getCourier(), requestDto.getTrackingNumber());
110	
111	        try {
112	            ShipmentStatus updatedStatus = orderShipmentCommandService.updateAndCheckShipmentStatus(
113	                    shipmentId,
114	                    requestDto.getCourier(),
115	                    requestDto.getTrackingNumber()
116	            );
117	
118	            log.info("배송 상태 조회 완료 (문자열 응답): shipmentId={}, status={}",
119	                    shipmentId, updatedStatus);
120	
121	            // 문자열로 반환
122	            return ResponseEntity.ok(updatedStatus.name());
123	
124	        } catch (ShipmentException e) {
125	            log.error("배송 상태 문자열 조회 실패 (ShipmentException): shipmentId={}, code={}, message={}",
126	                    shipmentId, e.getErrorCode().getCode(), e.getMessage());
127	
128	            return ResponseEntity
129	                    .status(e.getErrorCode().getStatus())
130	                    .body("Error: " + e.getMessage());
131	
132	        } catch (Exception e) {
133	            log.error("배송 상태 문자열 조회 실패 (일반 예외): shipmentId={}, error={}",
134	                    shipmentId, e.getMessage(), e);
135	
136	            return ResponseEntity.badRequest().body("Error: " + e.getMessage());
137	        }
138	    }
