244	    /**
245	     * 주문 완료에 따라 판매 상태를 'SOLD'로 변경합니다.
246	     *
247	     * @param orderId 주문 ID
248	     */
249	    @Transactional
250	    public void updateSaleStatusToSold(Long orderId) {
251	        log.info("판매 상태를 'SOLD'로 변경 시작: orderId={}", orderId);
252	
253	        // SaleBid 조회
254	        SaleBid saleBid = saleBidQueryService.findByOrderId(orderId);
255	        if (saleBid != null) {
256	            Sale sale = saleBid.getSale();
257	            if (sale != null && sale.getStatus().canTransitionTo(SaleStatus.SOLD)) {
258	                log.info("Sale 상태 'SOLD'로 변경: saleId={}, sellerId={}",
259	                        sale.getId(), sale.getSeller().getId());
260	
261	                sale.updateStatus(SaleStatus.SOLD); // 더티 체크에 의해 자동으로 업데이트됨
262	
263	                // 창고 상태 업데이트
264	                if (sale.isWarehouseStorage()) {
265	                    log.info("창고 보관 상품의 창고 상태 업데이트: saleId={}", sale.getId());
266	                    warehouseStorageCommandService.updateWarehouseStatusToSold(sale);
267	                }
268	
269	                // 판매자에게 알림 생성
270	                User seller = sale.getSeller();
271	                notificationCommandService.createNotification(
272	                        seller.getId(),
273	                        NotificationCategory.SHOPPING,
274	                        NotificationType.BID,
275	                        "상품이 성공적으로 판매 완료되었습니다. 판매 ID: " + sale.getId()
276	                );
277	
278	                log.info("판매자 알림 생성 완료: sellerId={}, saleId={}",
279	                        seller.getId(), sale.getId());
280	            } else {
281	                log.debug("Sale 상태 변경 불가 또는 Sale이 null: saleBidId={}", saleBid.getId());
282	            }
283	        } else {
284	            log.debug("해당 주문과 연결된 SaleBid가 없음: orderId={}", orderId);
285	        }
286	
287	        // OrderBid 조회
288	        try {
289	            OrderBid orderBid = orderBidQueryService.findByOrderId(orderId)
290	                    .orElseThrow(() -> new IllegalArgumentException("해당 OrderBid를 찾을 수 없습니다: " + orderId));
291	
292	            if (orderBid != null) {
293	                Sale sale = orderBid.getSale();
294	                if (sale != null && sale.getStatus().canTransitionTo(SaleStatus.SOLD)) {
295	                    log.info("OrderBid 기반 Sale 상태 'SOLD'로 변경: orderBidId={}, saleId={}",
296	                            orderBid.getId(), sale.getId());
297	
298	                    sale.updateStatus(SaleStatus.SOLD); // 더티 체크에 의해 자동으로 업데이트됨
299	
300	                    // 판매자에게 알림 생성
301	                    User seller = sale.getSeller();
302	                    notificationCommandService.createNotification(
303	                            seller.getId(),
304	                            NotificationCategory.SHOPPING,
305	                            NotificationType.BID,
306	                            "상품이 성공적으로 판매 완료되었습니다. 판매 ID: " + sale.getId()
307	                    );
308	
309	                    log.info("판매자 알림 생성 완료: sellerId={}, saleId={}",
310	                            seller.getId(), sale.getId());
311	                } else {
312	                    log.debug("Sale 상태 변경 불가 또는 Sale이 null: orderBidId={}", orderBid.getId());
313	                }
314	            }
315	        } catch (IllegalArgumentException e) {
316	            log.warn("OrderBid 조회 실패: orderId={}, error={}", orderId, e.getMessage());
317	            // OrderBid가 없는 경우 예외로 중단하지 않고 진행
318	        }
319	
320	        log.info("판매 상태 'SOLD' 변경 작업 완료: orderId={}", orderId);
321	    }
