323	    /**
324	     * 주문을 완료 상태로 변경하고 관련된 후속 작업을 처리합니다.
325	     *
326	     * @param orderId 완료할 주문 ID
327	     */
328	    @Transactional
329	    public void completeOrder(Long orderId) {
330	        log.info("주문 완료 처리 시작: orderId={}", orderId);
331	
332	        try {
333	            // OrderBid 조회
334	            OrderBid orderBid = orderBidQueryService.findByOrderId(orderId)
335	                    .orElseThrow(() -> new IllegalArgumentException("OrderBid가 존재하지 않습니다. orderId=" + orderId));
336	
337	            Order order = orderBid.getOrder();
338	            log.debug("주문 정보 조회: orderId={}, userId={}, currentStatus={}",
339	                    order.getId(), order.getUser().getId(), order.getStatus());
340	
341	            // 주문 상태를 COMPLETED로 변경
342	            order.updateStatus(OrderStatus.COMPLETED);
343	            log.info("주문 상태 COMPLETED로 변경: orderId={}", orderId);
344	
345	            // 판매 상태 변경 로직
346	            updateSaleStatusToSold(orderId);
347	
348	            // 주문 완료 알림
349	            User buyer = order.getUser();
350	            notificationCommandService.createNotification(
351	                    buyer.getId(),
352	                    NotificationCategory.SHOPPING,
353	                    NotificationType.BID,
354	                    "[completeOrder] 주문이 완료 처리되었습니다. 주문 ID: " + order.getId()
355	            );
356	
357	            log.info("구매자 알림 생성 완료: userId={}, orderId={}", buyer.getId(), order.getId());
358	
359	        } catch (Exception e) {
360	            log.error("주문 완료 처리 실패: orderId={}, error={}", orderId, e.getMessage(), e);
361	            throw new ShipmentException(
362	                    ShipmentErrorCode.ORDER_NOT_FOUND_FOR_SHIPMENT,
363	                    "주문 완료 처리 중 오류 발생: " + e.getMessage(),
364	                    e
365	            );
366	        }
367	    }
