369	    /**
370	     * 배송 정보에 운송장 정보를 업데이트하고 관련 상태를 변경합니다.
371	     *
372	     * @param shipmentId 배송 ID
373	     * @param courier 택배사 이름
374	     * @param trackingNumber 운송장 번호
375	     */
376	    @Transactional
377	    public void updateTrackingInfo(Long shipmentId, String courier, String trackingNumber) {
378	        log.info("배송 운송장 정보 업데이트: shipmentId={}, courier={}, trackingNumber={}",
379	                shipmentId, courier, trackingNumber);
380	
381	        if (courier == null || courier.isBlank() || trackingNumber == null || trackingNumber.isBlank()) {
382	            log.warn("유효하지 않은 배송사 또는 운송장 번호: shipmentId={}", shipmentId);
383	            throw new ShipmentException(ShipmentErrorCode.TRACKING_INFO_REQUIRED);
384	        }
385	
386	        try {
387	            OrderShipment shipment = orderShipmentRepository.findById(shipmentId)
388	                    .orElseThrow(() -> new ShipmentException(
389	                            ShipmentErrorCode.SHIPMENT_NOT_FOUND,
390	                            "Shipment 정보를 찾을 수 없습니다: " + shipmentId
391	                    ));
392	
393	            // 운송장 정보 업데이트
394	            shipment.updateTrackingInfo(courier, trackingNumber);
395	
396	            // 배송 상태가 변경되었으므로 주문 상태도 업데이트
397	            Order order = shipment.getOrder();
398	            order.updateStatus(OrderStatus.IN_TRANSIT);
399	
400	            log.info("주문 상태 IN_TRANSIT으로 업데이트: orderId={}", order.getId());
401	
402	            // 주문한 사용자에게 알림 생성
403	            User buyer = order.getUser();
404	            notificationCommandService.createNotification(
405	                    buyer.getId(),
406	                    NotificationCategory.SHOPPING,
407	                    NotificationType.BID,
408	                    "상품이 출발하였습니다. 주문 ID: " + order.getId()
409	            );
410	
411	            log.info("구매자 출발 알림 생성: userId={}, orderId={}", buyer.getId(), order.getId());
412	
413	            // 판매 상태 업데이트 및 알림 전송
414	            updateSaleStatusToSold(order.getId());
415	
416	            // SaleBid에서 Sale 조회 및 창고 상태 업데이트
417	            SaleBid saleBid = saleBidQueryService.findByOrderId(order.getId());
418	            if (saleBid != null) {
419	                Sale sale = saleBid.getSale();
420	                if (sale != null && sale.isWarehouseStorage()) {
421	                    log.info("창고 보관 상품의 창고 상태 업데이트: saleId={}", sale.getId());
422	                    warehouseStorageCommandService.updateWarehouseStatusToSold(sale);
423	                }
424	            }
425	
426	            // OrderBid 상태를 COMPLETED로 변경
427	            updateOrderAndSaleBidStatusToCompleted(order.getId());
428	
429	            log.info("운송장 정보 업데이트 완료: shipmentId={}", shipmentId);
430	
431	        } catch (ShipmentException e) {
432	            throw e;
433	        } catch (Exception e) {
434	            log.error("운송장 정보 업데이트 실패: shipmentId={}, error={}", shipmentId, e.getMessage(), e);
435	            throw new ShipmentException(
436	                    ShipmentErrorCode.SHIPMENT_NOT_FOUND,
437	                    "운송장 정보 업데이트 중 오류 발생: " + e.getMessage(),
438	                    e
439	            );
440	        }
441	    }
