531	    /**
532	     * 배송사 상태 텍스트를 내부 ShipmentStatus로 매핑합니다.
533	     *
534	     * @param statusText 배송사 상태 텍스트
535	     * @return 매핑된 ShipmentStatus
536	     */
537	    private ShipmentStatus mapToShipmentStatus(String statusText) {
538	        return switch (statusText) {
539	            case "배송완료" -> ShipmentStatus.DELIVERED;
540	            case "배송출발" -> ShipmentStatus.OUT_FOR_DELIVERY;
541	            default -> ShipmentStatus.IN_TRANSIT;
542	        };
543	    }
