545	    /**
546	     * OrderBid와 SaleBid의 상태를 COMPLETED로 업데이트합니다.
547	     *
548	     * @param orderId 주문 ID
549	     */
550	    @Transactional
551	    private void updateOrderAndSaleBidStatusToCompleted(Long orderId) {
552	        log.info("입찰 상태 COMPLETED로 변경: orderId={}", orderId);
553	
554	        try {
555	            // OrderBid 조회
556	            OrderBid orderBid = orderBidQueryService.findByOrderId(orderId)
557	                    .orElseThrow(() -> new IllegalArgumentException("해당 OrderBid를 찾을 수 없습니다: " + orderId));
558	
559	            // 상태를 COMPLETED로 업데이트
560	            if (orderBid.getStatus() == com.fream.back.domain.order.entity.BidStatus.MATCHED) {
561	                log.debug("OrderBid 상태 COMPLETED로 변경: orderBidId={}", orderBid.getId());
562	                orderBid.updateStatus(com.fream.back.domain.order.entity.BidStatus.COMPLETED);
563	            }
564	
565	            // SaleBid 상태 업데이트
566	            SaleBid saleBid = saleBidQueryService.findByOrderId(orderId);
567	            if (saleBid != null && saleBid.getStatus() == BidStatus.MATCHED) {
568	                log.debug("SaleBid 상태 COMPLETED로 변경: saleBidId={}", saleBid.getId());
569	                saleBid.updateStatus(BidStatus.COMPLETED);
570	            }
571	
572	            log.info("입찰 상태 COMPLETED 변경 완료: orderId={}", orderId);
573	
574	        } catch (Exception e) {
575	            log.error("입찰 상태 변경 실패: orderId={}, error={}", orderId, e.getMessage(), e);
576	            // 상태 변경 실패는 로그만 남기고 진행 (주요 로직에 영향 주지 않음)
577	        }
578	    }
