   125	    private String parseStatusFromHtml(String html, String trackingNumber) {
   126	        try {
   127	            Document doc = Jsoup.parse(html);
   128	            Elements rows = doc.select(STATUS_SELECTOR);
   129	
   130	            if (rows.isEmpty()) {
   131	                log.warn("배송 상태 테이블이 비어 있음: 운송장={}", trackingNumber);
   132	                throw new ShipmentException(
   133	                        ShipmentErrorCode.TRACKING_HTML_PARSE_ERROR,
   134	                        "배송 정보가 없습니다. 운송장 번호를 확인해주세요: " + trackingNumber
   135	                );
   136	            }
   137	
   138	            // 마지막 행(최신 상태)의 5번째 컬럼 선택
   139	            String statusText = rows.last().select("td").get(4).text().trim();
   140	
   141	            if (statusText.isEmpty()) {
   142	                log.warn("배송 상태 텍스트가 비어 있음: 운송장={}", trackingNumber);
   143	                throw new ShipmentException(
